import { execFileSync } from "node:child_process";
import { mkdir, readdir, writeFile } from "node:fs/promises";
import path from "node:path";
import process from "node:process";

const root = process.cwd();
const options = new Set(process.argv.slice(2));
for (const option of options) {
  if (option !== "--skip-build") throw new Error(`unknown option: ${option}`);
}
const modules = [
  ["ji-ai-api", "ji-java/core/ji-ai-api"],
  ["ji-agent-api", "ji-java/core/ji-agent-api"],
  ["ji-session-api", "ji-java/core/ji-session-api"],
  ["ji-security-api", "ji-java/core/ji-security-api"],
  ["ji-extension-api", "ji-java/core/ji-extension-api"],
  ["ji-artifact-api", "ji-java/core/ji-artifact-api"],
  ["ji-telemetry-api", "ji-java/core/ji-telemetry-api"],
  ["ji-error-catalog", "ji-java/protocols/ji-error-catalog"],
];

const gradleTasks = modules.map(([name]) => `:${name}:jar`);
if (!options.has("--skip-build")) {
  if (process.platform === "win32") {
    execFileSync(process.env.ComSpec ?? "cmd.exe", ["/d", "/s", "/c", path.join(root, "gradlew.bat"), ...gradleTasks], {
      cwd: root,
      stdio: "inherit",
    });
  } else {
    execFileSync(path.join(root, "gradlew"), gradleTasks, { cwd: root, stdio: "inherit" });
  }
}

const inventory = { schemaVersion: "1.0", version: "0.1.0", modules: {} };
for (const [name, relative] of modules) {
  const libs = path.join(root, relative, "build", "libs");
  const jar = (await readdir(libs)).find(file => file === `${name}-0.1.0-SNAPSHOT.jar`);
  if (!jar) throw new Error(`missing ${name} jar`);
  const classes = execFileSync("jar", ["tf", path.join(libs, jar)], { encoding: "utf8" })
    .split(/\r?\n/)
    .filter(value => value.endsWith(".class") && value !== "module-info.class" && !value.match(/\$\d|\$Builder\.class$/))
    .map(value => value.replaceAll("/", ".").replace(/\.class$/, ""))
    .sort();
  const signatures = [];
  for (const className of classes) {
    const output = execFileSync("javap", ["-public", "-classpath", path.join(libs, jar), className], { encoding: "utf8" });
    const lines = output.split(/\r?\n/)
      .map(line => line.trim())
      .filter(line => line && !line.startsWith("Compiled from") && line !== "{" && line !== "}")
      .map(line => line.replace(/;$/, ""));
    if (!lines[0]?.match(/^public (?:class|final class|abstract class|interface|record|enum|sealed interface|non-sealed )/)) continue;
    signatures.push(...lines);
  }
  inventory.modules[name] = [...new Set(signatures)].sort();
}

const outputPath = process.env.JI_API_BASELINE_OUTPUT
  ? path.resolve(process.env.JI_API_BASELINE_OUTPUT)
  : path.join(root, "docs", "java-rewrite", "api-baseline", "0.1.0-signatures.json");
await mkdir(path.dirname(outputPath), { recursive: true });
await writeFile(outputPath, `${JSON.stringify(inventory, null, 2)}\n`, "utf8");
process.stdout.write(`wrote ${path.relative(root, outputPath)}\n`);
